/* ==========================================================================
   LEDYVAS — Contrato de Distribuidor Oficial · texto en 5 idiomas (es/en/it/fr/pt)
   Un solo contrato: DISTRIBUIDOR OFICIAL (empresa). MODELO DE REVENTA
   (actualizado 2026-09-06, estilo programa de partners tipo QuickBooks QSP):
   el Distribuidor compra cada licencia de Ledyvas Enterprise al 80% del PVP,
   factura DIRECTAMENTE a su cliente final (su país, su moneda, su impuesto),
   retiene su margen (mínimo 20% del PVP) y abona el 80% a Ledyvas por
   adelantado, licencia por licencia. Ledyvas emite y activa la clave firmada
   SOLO tras recibir ese pago — nunca antes. Membresía US$199/año. Cuota de
   5 licencias en 150 días. Territorio de exclusividad acotado. El Distribuidor
   nombra a sus propios vendedores (aviso, sin aprobación; responde por ellos).
   ⚠️ BORRADOR. Revisión de Leo + asesor legal antes de uso.
   La versión en ESPAÑOL rige (ley de la República Dominicana); el resto es
   traducción de cortesía. Usado por contrato.html.
   ========================================================================== */
(function () {
  "use strict";

  var META = {
    es: { draft: "BORRADOR — sujeto a revisión legal. No firmar hasta que Ledyvas confirme la versión definitiva.", governs: "" },
    en: { draft: "DRAFT — subject to legal review. Do not sign until Ledyvas confirms the final version.", governs: "Courtesy translation. If there is any discrepancy, the Spanish version prevails (law of the Dominican Republic)." },
    it: { draft: "BOZZA — soggetta a revisione legale. Non firmare finché Ledyvas non conferma la versione definitiva.", governs: "Traduzione di cortesia. In caso di discrepanza prevale la versione in spagnolo (legge della Repubblica Dominicana)." },
    fr: { draft: "PROJET — sous réserve d'une révision juridique. Ne pas signer tant que Ledyvas n'a pas confirmé la version définitive.", governs: "Traduction de courtoisie. En cas de divergence, la version espagnole prévaut (droit de la République dominicaine)." },
    pt: { draft: "RASCUNHO — sujeito a revisão jurídica. Não assinar até a Ledyvas confirmar a versão definitiva.", governs: "Tradução de cortesia. Em caso de divergência, prevalece a versão em espanhol (lei da República Dominicana)." }
  };

  var TITLES = {
    distribuidor: { es: "Contrato de Distribuidor Oficial", en: "Official Distributor Agreement", it: "Contratto di Distributore Ufficiale", fr: "Contrat de Distributeur Officiel", pt: "Contrato de Distribuidor Oficial" }
  };

  var PARTIES = {
    distribuidor: {
      es: "Este contrato se celebra entre <b>Ledyvas</b> (Leonardo Cosci, RNC [pendiente], República Dominicana), en adelante “Ledyvas”, y la empresa identificada en la solicitud de distribuidor ya verificada, representada por su representante legal, en adelante “el Distribuidor”.",
      en: "This agreement is between <b>Ledyvas</b> (Leonardo Cosci, Tax ID [pending], Dominican Republic), “Ledyvas”, and the company identified in the already-verified distributor application, acting through its legal representative, “the Distributor”.",
      it: "Il presente contratto è stipulato tra <b>Ledyvas</b> (Leonardo Cosci, codice fiscale [in attesa], Repubblica Dominicana), “Ledyvas”, e l'impresa indicata nella domanda di distributore già verificata, rappresentata dal suo rappresentante legale, “il Distributore”.",
      fr: "Le présent contrat est conclu entre <b>Ledyvas</b> (Leonardo Cosci, identifiant fiscal [en attente], République dominicaine), « Ledyvas », et la société identifiée dans la demande de distributeur déjà vérifiée, agissant par son représentant légal, « le Distributeur ».",
      pt: "Este contrato é celebrado entre a <b>Ledyvas</b> (Leonardo Cosci, identificação fiscal [pendente], República Dominicana), “Ledyvas”, e a empresa identificada no pedido de distribuidor já verificado, representada pelo seu representante legal, “o Distribuidor”."
    }
  };

  // ---------------- CONTRATO DE DISTRIBUIDOR OFICIAL (modelo de reventa) ----------------
  var DISTRIBUIDOR = {
    es: [
      { t: "1. Objeto y designación", b: "Ledyvas designa al Distribuidor como <b>Distribuidor Oficial autorizado</b> para comercializar el software <b>Ledyvas Enterprise</b> a clientes finales dentro del territorio indicado en la cláusula 8. El Distribuidor actúa <b>por cuenta propia</b>: compra cada licencia a Ledyvas a precio mayorista y la revende a su cliente. No es empleado, socio, agente con poder de representación ni franquiciado de Ledyvas. Su ingreso proviene únicamente del margen sobre las licencias que revende a clientes finales; no recibe compensación por incorporar a otros distribuidores. Ledyvas no garantiza ningún nivel de ingresos." },
      { t: "2. Membresía", b: "El Distribuidor abona una membresía anual de <b>US$ 199</b>, por adelantado. La membresía da derecho a: la condición y el sello de “Distribuidor Oficial”; el listado en ledyvas.com; la exclusividad territorial de la cláusula 8; la derivación de las consultas de compra que Ledyvas reciba de ese territorio; el precio mayorista de la cláusula 3; el acceso al panel de control; la formación y la certificación; el soporte prioritario; y una (1) licencia de demostración de Ledyvas Enterprise, no revendible. No es reembolsable, salvo: (a) que Ledyvas no apruebe la solicitud, o (b) que el Distribuidor cancele dentro de los 14 días corridos desde la firma." },
      { t: "3. Precio mayorista y margen", b: "El precio del Distribuidor por cada licencia de Ledyvas Enterprise es el <b>80% del precio de venta al público (PVP) vigente</b> que Ledyvas publica en ledyvas.com/distribuidores. El Distribuidor revende a su cliente final a un precio <b>no inferior al PVP</b>; la diferencia entre lo que cobra a su cliente y el 80% que abona a Ledyvas es su margen, que <b>no será inferior al 20% del PVP</b>. Ledyvas puede modificar el PVP y el porcentaje mayorista para el período siguiente conforme a la cláusula 16." },
      { t: "4. Pedidos, pago y entrega de la licencia", b: "Por cada venta, el Distribuidor solicita la licencia desde su panel de control y <b>abona por adelantado el 80%</b> correspondiente. Una vez confirmado el pago en la cuenta de Ledyvas, Ledyvas <b>emite y activa</b> la clave de licencia firmada y la pone a disposición del Distribuidor para su entrega al cliente. <b>En ningún caso se emite ni se activa una licencia sin el pago previo.</b> El Distribuidor no tiene acceso al sistema de generación de licencias ni a las cuentas de otros distribuidores." },
      { t: "5. Facturación al cliente final y obligaciones fiscales", b: "El Distribuidor <b>factura directamente a su cliente final</b>, en su país, su moneda y conforme a su normativa fiscal, y es el único responsable de la relación comercial y contable con ese cliente. Ledyvas emite al Distribuidor la factura correspondiente por cada licencia adquirida, como exportación de servicios desde la República Dominicana. El Distribuidor no representa a Ledyvas ante ninguna autoridad fiscal ni asume obligaciones en nombre de Ledyvas." },
      { t: "6. Control de activación", b: "La licencia de Ledyvas Enterprise valida su activación contra el servidor de Ledyvas. Ledyvas puede suspender o desactivar cualquier licencia utilizada fuera de los términos de este contrato —duplicada, instalada en más equipos de los autorizados, o entregada sin haber sido adquirida conforme a la cláusula 4—, con notificación previa al Distribuidor cuando sea posible." },
      { t: "7. Reembolsos y contracargos", b: "La relación de pago entre el Distribuidor y su cliente final es ajena a Ledyvas: cualquier reembolso o disputa con el cliente la resuelve el Distribuidor. Ledyvas no reintegra el 80% ya abonado por una licencia, salvo defecto del software no subsanable en un plazo razonable. Un contracargo o un fraude en el pago del Distribuidor anula la licencia asociada." },
      { t: "8. Territorio", b: "Mientras la membresía esté vigente y la cuota de la cláusula 9 cumplida, la designación es <b>exclusiva en el territorio indicado</b> en la solicitud verificada. El territorio se delimita de común acuerdo en función del mercado de la zona, la capacidad de cobertura del Distribuidor y su volumen de ventas —habitualmente un área metropolitana o una zona urbana acotada, no una provincia ni un país—. En ese territorio, Ledyvas no designa otros Distribuidores Oficiales y le deriva las consultas de compra que reciba de esa zona. Ledyvas conserva el derecho de vender Ledyvas Pro directamente en cualquier lugar. Dentro de su territorio, el Distribuidor puede nombrar a sus propios vendedores (cláusula 10)." },
      { t: "9. Cuota de permanencia", b: "Para conservar la exclusividad y la condición de Distribuidor Oficial, el Distribuidor debe revender al menos <b>cinco (5) licencias de Ledyvas Enterprise dentro de los primeros ciento cincuenta (150) días</b> contados desde la finalización de la formación. Si no la alcanza, conserva la autorización para revender pero <b>pierde la exclusividad territorial, el sello, el listado y la derivación de consultas</b>, y su precio mayorista pasa al <b>85% del PVP</b> (margen mínimo 15%) por el resto del período anual. El importe de la membresía no se reembolsa." },
      { t: "10. Vendedores del Distribuidor", b: "El Distribuidor puede designar a sus propios vendedores para promover Ledyvas dentro de su territorio, <b>sin necesidad de aprobación de Ledyvas</b>: basta con comunicar y mantener actualizada la lista de esos vendedores. El Distribuidor los retribuye según lo que acuerde con cada uno, con cargo a su propio margen, y es el único responsable de su relación con ellos, de su remuneración, de sus impuestos y de su facturación. Esos vendedores no tienen relación contractual con Ledyvas ni derecho a reclamarle pago alguno. El Distribuidor responde ante Ledyvas por la conducta de esos vendedores y por el cumplimiento de la cláusula 11." },
      { t: "11. Obligaciones del Distribuidor", b: "Presentar el producto con fidelidad, sin promesas falsas ni garantías de resultados a terceros; mantener al menos una persona formada y certificada en Ledyvas; prestar a sus clientes el primer nivel de atención comercial (presentación, demostración, acompañamiento), derivando a Ledyvas las incidencias técnicas del software; no realizar ingeniería inversa, no descompilar ni sublicenciar el software; no registrar marcas, nombres comerciales ni dominios que contengan “Ledyvas” o resulten confundibles; cumplir la política comercial y de marca que Ledyvas comunique por escrito." },
      { t: "12. Obligaciones de Ledyvas", b: "Suministrar el software Ledyvas Enterprise y sus actualizaciones; emitir y activar las licencias conforme a la cláusula 4; prestar todo el soporte técnico y la atención al cliente del producto; proporcionar la formación, la certificación y el kit de marca; y comunicar con antelación razonable cualquier cambio de PVP, porcentaje mayorista o condiciones generales." },
      { t: "13. Uso de la marca", b: "El Distribuidor puede identificarse como “Distribuidor Oficial de Ledyvas” y usar el kit de marca que Ledyvas provea, únicamente para comercializar Ledyvas y mientras conserve esa condición. Al perder la condición de Distribuidor Oficial o al terminar el contrato, cesa todo uso de la marca en un plazo de cinco (5) días." },
      { t: "14. Confidencialidad", b: "Cada parte protege la información no pública de la otra: precios especiales, datos de clientes, hoja de ruta del producto, cifras internas y condiciones del programa. La obligación subsiste tras la terminación." },
      { t: "15. Protección de datos", b: "Los datos de clientes y prospectos que cada parte trate se usan únicamente para la comercialización de Ledyvas. Cada parte cumple la normativa de protección de datos que le sea aplicable. El Distribuidor es responsable del tratamiento de los datos de sus propios clientes finales." },
      { t: "16. Duración y terminación", b: "El contrato tiene una duración de <b>un (1) año</b> desde su firma y <b>no se renueva automáticamente</b>. Sesenta (60) días antes del vencimiento, Ledyvas comunica si ofrece la renovación y con qué términos (puede modificar la membresía, el PVP, el porcentaje mayorista y las condiciones generales). Como referencia del criterio de renovación: si el Distribuidor revendió quince (15) o más licencias en el período, Ledyvas ofrece la renovación con la membresía bonificada; si no revendió ninguna, el contrato termina al vencimiento; en los casos intermedios, la renovación se ofrece al precio de membresía vigente. Cualquiera de las partes puede terminar antes con treinta (30) días de aviso por escrito, sin causa. Ledyvas puede terminar de inmediato por incumplimiento de las cláusulas 4, 6, 11 o 13. A la terminación: el Distribuidor deja de usar la marca y de comercializar Ledyvas; las licencias ya revendidas a clientes finales siguen válidas y con soporte de Ledyvas." },
      { t: "17. Sin sociedad ni relación laboral", b: "Este contrato no crea sociedad, franquicia, agencia con poder de representación ni relación laboral entre las partes. El Distribuidor puede comercializar otros productos, incluso de la competencia, salvo pacto expreso en contrario." },
      { t: "18. Ley aplicable y resolución de disputas", b: "Este contrato se rige por el derecho de la <b>República Dominicana</b>, en particular por el Código Civil, el Código de Comercio y la Ley núm. 126-02 sobre Comercio Electrónico, Documentos y Firmas Digitales. Se excluye de forma expresa la aplicación de la Convención de las Naciones Unidas sobre los Contratos de Compraventa Internacional de Mercaderías (Viena, 1980). Las partes intentarán resolver de buena fe cualquier diferencia; de no lograrlo, se someten de forma exclusiva a los tribunales competentes de la República Dominicana, con renuncia expresa a cualquier otro fuero o jurisdicción, cualquiera sea el domicilio o la nacionalidad de las partes." },
      { t: "19. Firma electrónica", b: "Al marcar la casilla de aceptación y escribir el nombre completo del representante legal, el Distribuidor manifiesta su consentimiento y firma este contrato en los términos de la Ley núm. 126-02, con el mismo valor legal que una firma manuscrita. Ledyvas registra la fecha, la hora y la dirección IP de la firma como constancia." }
    ],
    en: [
      { t: "1. Purpose and appointment", b: "Ledyvas appoints the Distributor as an <b>authorized Official Distributor</b> to market the <b>Ledyvas Enterprise</b> software to end customers within the territory stated in clause 8. The Distributor acts <b>on its own account</b>: it buys each license from Ledyvas at a wholesale price and resells it to its client. It is not an employee, partner, agent with power of representation or franchisee of Ledyvas. Its income comes solely from the margin on the licenses it resells to end customers; it receives no compensation for bringing in other distributors. Ledyvas guarantees no level of income." },
      { t: "2. Membership", b: "The Distributor pays an annual membership fee of <b>US$ 199</b>, in advance. Membership grants: the status and badge of “Official Distributor”; a listing on ledyvas.com; the territorial exclusivity of clause 8; routing of the purchase enquiries Ledyvas receives from that territory; the wholesale price of clause 3; access to the control panel; training and certification; priority support; and one (1) non-resellable Ledyvas Enterprise demo license. It is non-refundable, except: (a) if Ledyvas does not approve the application, or (b) if the Distributor cancels within 14 calendar days of signature." },
      { t: "3. Wholesale price and margin", b: "The Distributor's price for each Ledyvas Enterprise license is <b>80% of the current recommended retail price (RRP)</b> published by Ledyvas at ledyvas.com/distribuidores. The Distributor resells to its end client at a price <b>no lower than the RRP</b>; the difference between what it charges its client and the 80% it pays Ledyvas is its margin, which <b>shall not be lower than 20% of the RRP</b>. Ledyvas may change the RRP and the wholesale percentage for the following term under clause 16." },
      { t: "4. Orders, payment and license delivery", b: "For each sale, the Distributor requests the license from its control panel and <b>pays the corresponding 80% in advance</b>. Once payment is confirmed in Ledyvas's account, Ledyvas <b>issues and activates</b> the signed license key and makes it available to the Distributor for delivery to the client. <b>No license is issued or activated without prior payment.</b> The Distributor has no access to the license-generation system or to other distributors' accounts." },
      { t: "5. Invoicing the end customer and tax obligations", b: "The Distributor <b>invoices its end customer directly</b>, in its country, its currency and in accordance with its tax rules, and is solely responsible for the commercial and accounting relationship with that customer. Ledyvas issues the Distributor the corresponding invoice for each license purchased, as an export of services from the Dominican Republic. The Distributor does not represent Ledyvas before any tax authority nor assume obligations on Ledyvas's behalf." },
      { t: "6. Activation control", b: "The Ledyvas Enterprise license validates its activation against the Ledyvas server. Ledyvas may suspend or deactivate any license used outside the terms of this agreement —duplicated, installed on more machines than authorized, or delivered without having been acquired under clause 4—, with prior notice to the Distributor where possible." },
      { t: "7. Refunds and chargebacks", b: "The payment relationship between the Distributor and its end customer is outside Ledyvas: any refund or dispute with the customer is resolved by the Distributor. Ledyvas does not refund the 80% already paid for a license, except for a software defect not remediable within a reasonable time. A chargeback or fraud in the Distributor's payment voids the associated license." },
      { t: "8. Territory", b: "While the membership is active and the clause 9 quota is met, the appointment is <b>exclusive in the stated territory</b> from the verified application. The territory is defined by mutual agreement based on the market of the area, the Distributor's coverage capacity and its sales volume —typically a metropolitan area or a defined urban zone, not a province or a country—. In that territory, Ledyvas appoints no other Official Distributors and routes to it the purchase enquiries it receives from that area. Ledyvas keeps the right to sell Ledyvas Pro directly anywhere. Within its territory, the Distributor may appoint its own salespeople (clause 10)." },
      { t: "9. Performance quota", b: "To keep the exclusivity and the Official Distributor status, the Distributor must resell at least <b>five (5) Ledyvas Enterprise licenses within the first one hundred and fifty (150) days</b> from completion of training. If it does not, it keeps the authorization to resell but <b>loses the territorial exclusivity, the badge, the listing and the enquiry routing</b>, and its wholesale price moves to <b>85% of the RRP</b> (minimum margin 15%) for the rest of the annual term. The membership fee is not refunded." },
      { t: "10. The Distributor's salespeople", b: "The Distributor may appoint its own salespeople to promote Ledyvas within its territory, <b>without Ledyvas's approval</b>: it is enough to send and keep up to date the list of those salespeople. The Distributor pays them as it agrees with each of them, out of its own margin, and is solely responsible for its relationship with them, their remuneration, their taxes and their invoicing. Those salespeople have no contractual relationship with Ledyvas and no right to claim any payment from it. The Distributor is answerable to Ledyvas for the conduct of those salespeople and for compliance with clause 11." },
      { t: "11. Distributor obligations", b: "Present the product faithfully, with no false promises or guarantees of results to third parties; keep at least one person trained and certified in Ledyvas; provide its clients with first-level commercial support (presentation, demonstration, follow-up), routing software technical incidents to Ledyvas; not reverse-engineer, decompile or sublicense the software; not register trademarks, trade names or domains containing “Ledyvas” or confusingly similar; comply with the commercial and brand policy Ledyvas communicates in writing." },
      { t: "12. Ledyvas obligations", b: "Supply the Ledyvas Enterprise software and its updates; issue and activate licenses under clause 4; provide all product technical support and customer care; provide training, certification and the brand kit; and give reasonable advance notice of any change to the RRP, the wholesale percentage or the general terms." },
      { t: "13. Brand use", b: "The Distributor may identify itself as an “Official Ledyvas Distributor” and use the brand kit Ledyvas provides, only to market Ledyvas and while it keeps that status. On losing Official Distributor status or on termination of the agreement, all brand use ceases within five (5) days." },
      { t: "14. Confidentiality", b: "Each party protects the other's non-public information: special prices, customer data, product roadmap, internal figures and program terms. The obligation survives termination." },
      { t: "15. Data protection", b: "The customer and prospect data each party processes is used only to market Ledyvas. Each party complies with the data-protection rules applicable to it. The Distributor is the controller of its own end customers' data." },
      { t: "16. Term and termination", b: "The agreement runs for <b>one (1) year</b> from signature and <b>does not renew automatically</b>. Sixty (60) days before expiry, Ledyvas states whether it offers renewal and on what terms (it may change the membership, the RRP, the wholesale percentage and the general terms). As a reference for the renewal criterion: if the Distributor resold fifteen (15) or more licenses in the term, Ledyvas offers renewal with a subsidized membership; if it resold none, the agreement ends at expiry; in between, renewal is offered at the then-current membership price. Either party may terminate earlier with thirty (30) days' written notice, without cause. Ledyvas may terminate immediately for breach of clauses 4, 6, 11 or 13. On termination: the Distributor stops using the brand and marketing Ledyvas; licenses already resold to end customers remain valid and supported by Ledyvas." },
      { t: "17. No partnership or employment", b: "This agreement creates no partnership, franchise, agency with power of representation or employment relationship between the parties. The Distributor may market other products, including competing ones, unless expressly agreed otherwise." },
      { t: "18. Governing law and dispute resolution", b: "This agreement is governed by the law of the <b>Dominican Republic</b>, in particular the Civil Code, the Commercial Code and Law No. 126-02 on Electronic Commerce, Documents and Digital Signatures. The application of the United Nations Convention on Contracts for the International Sale of Goods (Vienna, 1980) is expressly excluded. The parties will try to resolve any difference in good faith; failing that, they submit exclusively to the competent courts of the Dominican Republic, expressly waiving any other forum or jurisdiction, whatever the domicile or nationality of the parties." },
      { t: "19. Electronic signature", b: "By ticking the acceptance box and typing the full name of the legal representative, the Distributor gives its consent and signs this agreement under Law No. 126-02, with the same legal value as a handwritten signature. Ledyvas records the date, time and IP address of the signature as evidence." }
    ],
    it: [
      { t: "1. Oggetto e nomina", b: "Ledyvas nomina il Distributore come <b>Distributore Ufficiale autorizzato</b> a commercializzare il software <b>Ledyvas Enterprise</b> a clienti finali nel territorio indicato alla clausola 8. Il Distributore agisce <b>per conto proprio</b>: acquista ogni licenza da Ledyvas a un prezzo all'ingrosso e la rivende al proprio cliente. Non è dipendente, socio, agente con potere di rappresentanza né affiliato di Ledyvas. Il suo reddito deriva unicamente dal margine sulle licenze che rivende a clienti finali; non riceve compensi per l'inserimento di altri distributori. Ledyvas non garantisce alcun livello di reddito." },
      { t: "2. Adesione", b: "Il Distributore versa una quota di adesione annuale di <b>US$ 199</b>, in anticipo. L'adesione dà diritto a: lo status e il marchio di “Distributore Ufficiale”; l'inserimento su ledyvas.com; l'esclusiva territoriale della clausola 8; l'inoltro delle richieste d'acquisto che Ledyvas riceve da quel territorio; il prezzo all'ingrosso della clausola 3; l'accesso al pannello di controllo; la formazione e la certificazione; l'assistenza prioritaria; e una (1) licenza dimostrativa di Ledyvas Enterprise, non rivendibile. Non è rimborsabile, salvo: (a) se Ledyvas non approva la domanda, o (b) se il Distributore annulla entro 14 giorni di calendario dalla firma." },
      { t: "3. Prezzo all'ingrosso e margine", b: "Il prezzo del Distributore per ogni licenza di Ledyvas Enterprise è l'<b>80% del prezzo di vendita al pubblico (PVP) vigente</b> pubblicato da Ledyvas su ledyvas.com/distribuidores. Il Distributore rivende al proprio cliente finale a un prezzo <b>non inferiore al PVP</b>; la differenza tra quanto addebita al cliente e l'80% che versa a Ledyvas è il suo margine, che <b>non sarà inferiore al 20% del PVP</b>. Ledyvas può modificare il PVP e la percentuale all'ingrosso per il periodo successivo ai sensi della clausola 16." },
      { t: "4. Ordini, pagamento e consegna della licenza", b: "Per ogni vendita, il Distributore richiede la licenza dal proprio pannello di controllo e <b>versa in anticipo l'80%</b> corrispondente. Una volta confermato il pagamento sul conto di Ledyvas, Ledyvas <b>emette e attiva</b> la chiave di licenza firmata e la mette a disposizione del Distributore per la consegna al cliente. <b>In nessun caso una licenza viene emessa o attivata senza il pagamento anticipato.</b> Il Distributore non ha accesso al sistema di generazione delle licenze né ai conti di altri distributori." },
      { t: "5. Fatturazione al cliente finale e obblighi fiscali", b: "Il Distributore <b>fattura direttamente al proprio cliente finale</b>, nel proprio paese, nella propria valuta e secondo la propria normativa fiscale, ed è l'unico responsabile del rapporto commerciale e contabile con quel cliente. Ledyvas emette al Distributore la relativa fattura per ogni licenza acquistata, come esportazione di servizi dalla Repubblica Dominicana. Il Distributore non rappresenta Ledyvas davanti ad alcuna autorità fiscale né assume obblighi a nome di Ledyvas." },
      { t: "6. Controllo dell'attivazione", b: "La licenza di Ledyvas Enterprise convalida la propria attivazione sul server di Ledyvas. Ledyvas può sospendere o disattivare qualsiasi licenza usata al di fuori dei termini del presente contratto —duplicata, installata su più dispositivi di quelli autorizzati, o consegnata senza essere stata acquistata ai sensi della clausola 4—, con preavviso al Distributore quando possibile." },
      { t: "7. Rimborsi e storni", b: "Il rapporto di pagamento tra il Distributore e il proprio cliente finale è estraneo a Ledyvas: qualsiasi rimborso o controversia con il cliente è risolto dal Distributore. Ledyvas non restituisce l'80% già versato per una licenza, salvo un difetto del software non sanabile in un tempo ragionevole. Uno storno o una frode nel pagamento del Distributore annulla la licenza associata." },
      { t: "8. Territorio", b: "Finché l'adesione è attiva e la quota della clausola 9 è rispettata, la nomina è <b>esclusiva nel territorio indicato</b> nella domanda verificata. Il territorio è delimitato di comune accordo in base al mercato della zona, alla capacità di copertura del Distributore e al suo volume di vendite —abitualmente un'area metropolitana o una zona urbana delimitata, non una provincia né un paese—. In quel territorio, Ledyvas non nomina altri Distributori Ufficiali e gli inoltra le richieste d'acquisto che riceve da quella zona. Ledyvas conserva il diritto di vendere Ledyvas Pro direttamente ovunque. Nel proprio territorio, il Distributore può nominare i propri venditori (clausola 10)." },
      { t: "9. Quota di permanenza", b: "Per conservare l'esclusiva e lo status di Distributore Ufficiale, il Distributore deve rivendere almeno <b>cinque (5) licenze di Ledyvas Enterprise entro i primi centocinquanta (150) giorni</b> dalla fine della formazione. In caso contrario, mantiene l'autorizzazione a rivendere ma <b>perde l'esclusiva territoriale, il marchio, l'inserimento e l'inoltro delle richieste</b>, e il suo prezzo all'ingrosso passa all'<b>85% del PVP</b> (margine minimo 15%) per il resto del periodo annuale. L'importo dell'adesione non viene rimborsato." },
      { t: "10. I venditori del Distributore", b: "Il Distributore può nominare i propri venditori per promuovere Ledyvas nel proprio territorio, <b>senza approvazione di Ledyvas</b>: è sufficiente comunicare e tenere aggiornato l'elenco di tali venditori. Il Distributore li retribuisce secondo quanto concordato con ciascuno, a carico del proprio margine, ed è l'unico responsabile del rapporto con loro, della loro remunerazione, delle loro imposte e della loro fatturazione. Tali venditori non hanno alcun rapporto contrattuale con Ledyvas né diritto a reclamarle alcun pagamento. Il Distributore risponde a Ledyvas della condotta di tali venditori e del rispetto della clausola 11." },
      { t: "11. Obblighi del Distributore", b: "Presentare il prodotto con fedeltà, senza false promesse né garanzie di risultati a terzi; mantenere almeno una persona formata e certificata in Ledyvas; fornire ai propri clienti il primo livello di assistenza commerciale (presentazione, dimostrazione, accompagnamento), inoltrando a Ledyvas gli incidenti tecnici del software; non effettuare ingegneria inversa, non decompilare né concedere sottolicenze del software; non registrare marchi, denominazioni commerciali o domini che contengano “Ledyvas” o che siano confondibili; rispettare la politica commerciale e di marca che Ledyvas comunica per iscritto." },
      { t: "12. Obblighi di Ledyvas", b: "Fornire il software Ledyvas Enterprise e i suoi aggiornamenti; emettere e attivare le licenze ai sensi della clausola 4; fornire tutta l'assistenza tecnica e il servizio clienti del prodotto; fornire la formazione, la certificazione e il kit di marca; e comunicare con ragionevole preavviso qualsiasi modifica del PVP, della percentuale all'ingrosso o delle condizioni generali." },
      { t: "13. Uso del marchio", b: "Il Distributore può identificarsi come “Distributore Ufficiale di Ledyvas” e usare il kit di marca fornito da Ledyvas, solo per commercializzare Ledyvas e finché mantiene tale status. Alla perdita dello status di Distributore Ufficiale o alla cessazione del contratto, ogni uso del marchio cessa entro cinque (5) giorni." },
      { t: "14. Riservatezza", b: "Ciascuna parte protegge le informazioni non pubbliche dell'altra: prezzi speciali, dati dei clienti, roadmap del prodotto, cifre interne e condizioni del programma. L'obbligo sopravvive alla cessazione." },
      { t: "15. Protezione dei dati", b: "I dati di clienti e potenziali clienti trattati da ciascuna parte sono usati solo per la commercializzazione di Ledyvas. Ciascuna parte rispetta la normativa sulla protezione dei dati a essa applicabile. Il Distributore è titolare del trattamento dei dati dei propri clienti finali." },
      { t: "16. Durata e cessazione", b: "Il contratto ha una durata di <b>un (1) anno</b> dalla firma e <b>non si rinnova automaticamente</b>. Sessanta (60) giorni prima della scadenza, Ledyvas comunica se offre il rinnovo e a quali condizioni (può modificare l'adesione, il PVP, la percentuale all'ingrosso e le condizioni generali). Come riferimento del criterio di rinnovo: se il Distributore ha rivenduto quindici (15) o più licenze nel periodo, Ledyvas offre il rinnovo con l'adesione agevolata; se non ne ha rivenduta nessuna, il contratto termina alla scadenza; nei casi intermedi, il rinnovo è offerto al prezzo di adesione in vigore. Ciascuna parte può recedere prima con preavviso scritto di trenta (30) giorni, senza giusta causa. Ledyvas può recedere con effetto immediato per violazione delle clausole 4, 6, 11 o 13. Alla cessazione: il Distributore smette di usare il marchio e di commercializzare Ledyvas; le licenze già rivendute a clienti finali restano valide e assistite da Ledyvas." },
      { t: "17. Nessuna società né rapporto di lavoro", b: "Il presente contratto non crea società, franchising, agenzia con potere di rappresentanza né rapporto di lavoro tra le parti. Il Distributore può commercializzare altri prodotti, anche concorrenti, salvo patto espresso contrario." },
      { t: "18. Legge applicabile e risoluzione delle controversie", b: "Il presente contratto è regolato dal diritto della <b>Repubblica Dominicana</b>, in particolare dal Codice Civile, dal Codice di Commercio e dalla Legge n. 126-02 sul Commercio Elettronico, Documenti e Firme Digitali. È espressamente esclusa l'applicazione della Convenzione delle Nazioni Unite sui Contratti di Compravendita Internazionale di Merci (Vienna, 1980). Le parti cercheranno di risolvere in buona fede ogni divergenza; in mancanza, si sottomettono in via esclusiva ai tribunali competenti della Repubblica Dominicana, rinunciando espressamente a qualsiasi altro foro o giurisdizione, qualunque sia il domicilio o la nazionalità delle parti." },
      { t: "19. Firma elettronica", b: "Selezionando la casella di accettazione e digitando il nome completo del rappresentante legale, il Distributore presta il consenso e firma il presente contratto ai sensi della Legge n. 126-02, con lo stesso valore legale di una firma autografa. Ledyvas registra la data, l'ora e l'indirizzo IP della firma come prova." }
    ],
    fr: [
      { t: "1. Objet et désignation", b: "Ledyvas désigne le Distributeur comme <b>Distributeur Officiel agréé</b> pour commercialiser le logiciel <b>Ledyvas Enterprise</b> auprès de clients finaux sur le territoire indiqué à la clause 8. Le Distributeur agit <b>pour son propre compte</b> : il achète chaque licence à Ledyvas à un prix de gros et la revend à son client. Il n'est ni salarié, ni associé, ni agent avec pouvoir de représentation, ni franchisé de Ledyvas. Ses revenus proviennent uniquement de la marge sur les licences qu'il revend à des clients finaux ; il ne perçoit aucune rémunération pour l'apport d'autres distributeurs. Ledyvas ne garantit aucun niveau de revenu." },
      { t: "2. Adhésion", b: "Le Distributeur paie une adhésion annuelle de <b>199 US$</b>, d'avance. L'adhésion donne droit à : le statut et le label de « Distributeur Officiel » ; une inscription sur ledyvas.com ; l'exclusivité territoriale de la clause 8 ; l'acheminement des demandes d'achat que Ledyvas reçoit de ce territoire ; le prix de gros de la clause 3 ; l'accès au tableau de bord ; la formation et la certification ; un support prioritaire ; et une (1) licence de démonstration Ledyvas Enterprise, non revendable. Elle n'est pas remboursable, sauf : (a) si Ledyvas n'approuve pas la demande, ou (b) si le Distributeur annule dans les 14 jours calendaires suivant la signature." },
      { t: "3. Prix de gros et marge", b: "Le prix du Distributeur pour chaque licence Ledyvas Enterprise est de <b>80 % du prix de vente au public (PVP) en vigueur</b> publié par Ledyvas sur ledyvas.com/distribuidores. Le Distributeur revend à son client final à un prix <b>non inférieur au PVP</b> ; la différence entre ce qu'il facture à son client et les 80 % qu'il verse à Ledyvas est sa marge, qui <b>ne sera pas inférieure à 20 % du PVP</b>. Ledyvas peut modifier le PVP et le pourcentage de gros pour la période suivante conformément à la clause 16." },
      { t: "4. Commandes, paiement et remise de la licence", b: "Pour chaque vente, le Distributeur demande la licence depuis son tableau de bord et <b>verse d'avance les 80 %</b> correspondants. Une fois le paiement confirmé sur le compte de Ledyvas, Ledyvas <b>émet et active</b> la clé de licence signée et la met à disposition du Distributeur pour remise au client. <b>En aucun cas une licence n'est émise ou activée sans paiement préalable.</b> Le Distributeur n'a pas accès au système de génération des licences ni aux comptes des autres distributeurs." },
      { t: "5. Facturation au client final et obligations fiscales", b: "Le Distributeur <b>facture directement son client final</b>, dans son pays, sa monnaie et conformément à ses règles fiscales, et il est seul responsable de la relation commerciale et comptable avec ce client. Ledyvas émet au Distributeur la facture correspondante pour chaque licence achetée, en tant qu'exportation de services depuis la République dominicaine. Le Distributeur ne représente Ledyvas devant aucune autorité fiscale et n'assume aucune obligation au nom de Ledyvas." },
      { t: "6. Contrôle de l'activation", b: "La licence Ledyvas Enterprise valide son activation auprès du serveur de Ledyvas. Ledyvas peut suspendre ou désactiver toute licence utilisée en dehors des termes du présent contrat —dupliquée, installée sur plus de postes qu'autorisé, ou remise sans avoir été acquise selon la clause 4—, avec préavis au Distributeur lorsque c'est possible." },
      { t: "7. Remboursements et rétrofacturations", b: "La relation de paiement entre le Distributeur et son client final est étrangère à Ledyvas : tout remboursement ou litige avec le client est réglé par le Distributeur. Ledyvas ne rembourse pas les 80 % déjà versés pour une licence, sauf défaut du logiciel non corrigeable dans un délai raisonnable. Une rétrofacturation ou une fraude sur le paiement du Distributeur annule la licence associée." },
      { t: "8. Territoire", b: "Tant que l'adhésion est active et le quota de la clause 9 atteint, la désignation est <b>exclusive sur le territoire indiqué</b> dans la demande vérifiée. Le territoire est délimité d'un commun accord en fonction du marché de la zone, de la capacité de couverture du Distributeur et de son volume de ventes —habituellement une aire métropolitaine ou une zone urbaine délimitée, pas une province ni un pays—. Sur ce territoire, Ledyvas ne désigne pas d'autres Distributeurs Officiels et lui achemine les demandes d'achat qu'elle reçoit de cette zone. Ledyvas conserve le droit de vendre Ledyvas Pro directement partout. Sur son territoire, le Distributeur peut nommer ses propres vendeurs (clause 10)." },
      { t: "9. Quota de maintien", b: "Pour conserver l'exclusivité et le statut de Distributeur Officiel, le Distributeur doit revendre au moins <b>cinq (5) licences Ledyvas Enterprise dans les cent cinquante (150) premiers jours</b> à compter de la fin de la formation. À défaut, il conserve l'autorisation de revendre mais <b>perd l'exclusivité territoriale, le label, l'inscription et l'acheminement des demandes</b>, et son prix de gros passe à <b>85 % du PVP</b> (marge minimale 15 %) pour le reste de la période annuelle. Le montant de l'adhésion n'est pas remboursé." },
      { t: "10. Les vendeurs du Distributeur", b: "Le Distributeur peut désigner ses propres vendeurs pour promouvoir Ledyvas sur son territoire, <b>sans l'approbation de Ledyvas</b> : il suffit de communiquer et de tenir à jour la liste de ces vendeurs. Le Distributeur les rémunère selon ce qu'il convient avec chacun, sur sa propre marge, et il est seul responsable de sa relation avec eux, de leur rémunération, de leurs impôts et de leur facturation. Ces vendeurs n'ont aucune relation contractuelle avec Ledyvas ni aucun droit de lui réclamer un paiement. Le Distributeur répond devant Ledyvas de la conduite de ces vendeurs et du respect de la clause 11." },
      { t: "11. Obligations du Distributeur", b: "Présenter le produit fidèlement, sans fausses promesses ni garanties de résultats à des tiers ; maintenir au moins une personne formée et certifiée Ledyvas ; assurer à ses clients le premier niveau d'accompagnement commercial (présentation, démonstration, suivi), en renvoyant à Ledyvas les incidents techniques du logiciel ; ne pas faire d'ingénierie inverse, ne pas décompiler ni sous-licencier le logiciel ; ne pas déposer de marques, noms commerciaux ou domaines contenant « Ledyvas » ou prêtant à confusion ; respecter la politique commerciale et de marque communiquée par écrit par Ledyvas." },
      { t: "12. Obligations de Ledyvas", b: "Fournir le logiciel Ledyvas Enterprise et ses mises à jour ; émettre et activer les licences selon la clause 4 ; assurer tout le support technique et le service client du produit ; fournir la formation, la certification et le kit de marque ; et communiquer avec un préavis raisonnable toute modification du PVP, du pourcentage de gros ou des conditions générales." },
      { t: "13. Usage de la marque", b: "Le Distributeur peut se présenter comme « Distributeur Officiel de Ledyvas » et utiliser le kit de marque fourni par Ledyvas, uniquement pour commercialiser Ledyvas et tant qu'il conserve ce statut. À la perte du statut de Distributeur Officiel ou à la fin du contrat, tout usage de la marque cesse dans un délai de cinq (5) jours." },
      { t: "14. Confidentialité", b: "Chaque partie protège les informations non publiques de l'autre : prix spéciaux, données clients, feuille de route produit, chiffres internes et conditions du programme. L'obligation survit à la résiliation." },
      { t: "15. Protection des données", b: "Les données de clients et de prospects traitées par chaque partie ne sont utilisées que pour commercialiser Ledyvas. Chaque partie respecte la réglementation de protection des données qui lui est applicable. Le Distributeur est responsable du traitement des données de ses propres clients finaux." },
      { t: "16. Durée et résiliation", b: "Le contrat court pour <b>un (1) an</b> à compter de la signature et <b>ne se renouvelle pas automatiquement</b>. Soixante (60) jours avant l'échéance, Ledyvas indique si elle propose le renouvellement et à quelles conditions (elle peut modifier l'adhésion, le PVP, le pourcentage de gros et les conditions générales). À titre de référence du critère de renouvellement : si le Distributeur a revendu quinze (15) licences ou plus sur la période, Ledyvas propose le renouvellement avec l'adhésion réduite ; s'il n'en a revendu aucune, le contrat prend fin à l'échéance ; entre les deux, le renouvellement est proposé au prix d'adhésion en vigueur. Chaque partie peut résilier plus tôt avec un préavis écrit de trente (30) jours, sans motif. Ledyvas peut résilier immédiatement en cas de manquement aux clauses 4, 6, 11 ou 13. À la résiliation : le Distributeur cesse d'utiliser la marque et de commercialiser Ledyvas ; les licences déjà revendues aux clients finaux restent valables et prises en charge par Ledyvas." },
      { t: "17. Ni société ni relation de travail", b: "Le présent contrat ne crée ni société, ni franchise, ni agence avec pouvoir de représentation, ni relation de travail entre les parties. Le Distributeur peut commercialiser d'autres produits, y compris concurrents, sauf accord exprès contraire." },
      { t: "18. Droit applicable et règlement des litiges", b: "Le présent contrat est régi par le droit de la <b>République dominicaine</b>, en particulier le Code civil, le Code de commerce et la Loi n° 126-02 sur le Commerce électronique, les Documents et les Signatures numériques. L'application de la Convention des Nations Unies sur les contrats de vente internationale de marchandises (Vienne, 1980) est expressément exclue. Les parties s'efforceront de régler tout différend de bonne foi ; à défaut, elles se soumettent exclusivement aux tribunaux compétents de la République dominicaine, en renonçant expressément à tout autre for ou juridiction, quels que soient le domicile ou la nationalité des parties." },
      { t: "19. Signature électronique", b: "En cochant la case d'acceptation et en saisissant le nom complet du représentant légal, le Distributeur donne son consentement et signe le présent contrat au titre de la Loi n° 126-02, avec la même valeur juridique qu'une signature manuscrite. Ledyvas enregistre la date, l'heure et l'adresse IP de la signature comme preuve." }
    ],
    pt: [
      { t: "1. Objeto e nomeação", b: "A Ledyvas nomeia o Distribuidor como <b>Distribuidor Oficial autorizado</b> para comercializar o software <b>Ledyvas Enterprise</b> a clientes finais no território indicado na cláusula 8. O Distribuidor atua <b>por conta própria</b>: compra cada licença à Ledyvas a um preço grossista e revende-a ao seu cliente. Não é empregado, sócio, agente com poder de representação nem franquiado da Ledyvas. O seu rendimento provém unicamente da margem sobre as licenças que revende a clientes finais; não recebe compensação por integrar outros distribuidores. A Ledyvas não garante qualquer nível de rendimento." },
      { t: "2. Adesão", b: "O Distribuidor paga uma adesão anual de <b>US$ 199</b>, antecipadamente. A adesão dá direito a: o estatuto e o selo de “Distribuidor Oficial”; a listagem em ledyvas.com; a exclusividade territorial da cláusula 8; o encaminhamento das consultas de compra que a Ledyvas receba desse território; o preço grossista da cláusula 3; o acesso ao painel de controlo; a formação e a certificação; o suporte prioritário; e uma (1) licença de demonstração do Ledyvas Enterprise, não revendável. Não é reembolsável, salvo: (a) se a Ledyvas não aprovar o pedido, ou (b) se o Distribuidor cancelar no prazo de 14 dias corridos desde a assinatura." },
      { t: "3. Preço grossista e margem", b: "O preço do Distribuidor por cada licença do Ledyvas Enterprise é <b>80% do preço de venda ao público (PVP) em vigor</b> publicado pela Ledyvas em ledyvas.com/distribuidores. O Distribuidor revende ao seu cliente final a um preço <b>não inferior ao PVP</b>; a diferença entre o que cobra ao seu cliente e os 80% que paga à Ledyvas é a sua margem, que <b>não será inferior a 20% do PVP</b>. A Ledyvas pode alterar o PVP e a percentagem grossista para o período seguinte nos termos da cláusula 16." },
      { t: "4. Encomendas, pagamento e entrega da licença", b: "Por cada venda, o Distribuidor solicita a licença a partir do seu painel de controlo e <b>paga antecipadamente os 80%</b> correspondentes. Confirmado o pagamento na conta da Ledyvas, a Ledyvas <b>emite e ativa</b> a chave de licença assinada e disponibiliza-a ao Distribuidor para entrega ao cliente. <b>Em nenhum caso é emitida ou ativada uma licença sem o pagamento prévio.</b> O Distribuidor não tem acesso ao sistema de geração de licenças nem às contas de outros distribuidores." },
      { t: "5. Faturação ao cliente final e obrigações fiscais", b: "O Distribuidor <b>fatura diretamente ao seu cliente final</b>, no seu país, na sua moeda e conforme a sua normativa fiscal, e é o único responsável pela relação comercial e contabilística com esse cliente. A Ledyvas emite ao Distribuidor a respetiva fatura por cada licença adquirida, como exportação de serviços a partir da República Dominicana. O Distribuidor não representa a Ledyvas perante qualquer autoridade fiscal nem assume obrigações em nome da Ledyvas." },
      { t: "6. Controlo da ativação", b: "A licença do Ledyvas Enterprise valida a sua ativação no servidor da Ledyvas. A Ledyvas pode suspender ou desativar qualquer licença usada fora dos termos do presente contrato —duplicada, instalada em mais equipamentos do que os autorizados, ou entregue sem ter sido adquirida nos termos da cláusula 4—, com aviso prévio ao Distribuidor quando possível." },
      { t: "7. Reembolsos e estornos", b: "A relação de pagamento entre o Distribuidor e o seu cliente final é alheia à Ledyvas: qualquer reembolso ou disputa com o cliente é resolvido pelo Distribuidor. A Ledyvas não devolve os 80% já pagos por uma licença, salvo defeito do software não sanável num prazo razoável. Um estorno ou fraude no pagamento do Distribuidor anula a licença associada." },
      { t: "8. Território", b: "Enquanto a adesão estiver ativa e a quota da cláusula 9 cumprida, a nomeação é <b>exclusiva no território indicado</b> no pedido verificado. O território é delimitado de comum acordo em função do mercado da zona, da capacidade de cobertura do Distribuidor e do seu volume de vendas —habitualmente uma área metropolitana ou uma zona urbana delimitada, não uma província nem um país—. Nesse território, a Ledyvas não nomeia outros Distribuidores Oficiais e encaminha-lhe as consultas de compra que receba dessa zona. A Ledyvas conserva o direito de vender o Ledyvas Pro diretamente em qualquer lugar. Dentro do seu território, o Distribuidor pode nomear os seus próprios vendedores (cláusula 10)." },
      { t: "9. Quota de permanência", b: "Para conservar a exclusividade e o estatuto de Distribuidor Oficial, o Distribuidor deve revender pelo menos <b>cinco (5) licenças do Ledyvas Enterprise nos primeiros cento e cinquenta (150) dias</b> a contar do fim da formação. Se não o fizer, mantém a autorização para revender mas <b>perde a exclusividade territorial, o selo, a listagem e o encaminhamento de consultas</b>, e o seu preço grossista passa a <b>85% do PVP</b> (margem mínima 15%) pelo resto do período anual. O valor da adesão não é reembolsado." },
      { t: "10. Os vendedores do Distribuidor", b: "O Distribuidor pode designar os seus próprios vendedores para promover o Ledyvas dentro do seu território, <b>sem necessidade de aprovação da Ledyvas</b>: basta comunicar e manter atualizada a lista desses vendedores. O Distribuidor remunera-os conforme o que acordar com cada um, a cargo da sua própria margem, e é o único responsável pela relação com eles, pela sua remuneração, pelos seus impostos e pela sua faturação. Esses vendedores não têm relação contratual com a Ledyvas nem direito a reclamar-lhe qualquer pagamento. O Distribuidor responde perante a Ledyvas pela conduta desses vendedores e pelo cumprimento da cláusula 11." },
      { t: "11. Obrigações do Distribuidor", b: "Apresentar o produto com fidelidade, sem falsas promessas nem garantias de resultados a terceiros; manter pelo menos uma pessoa formada e certificada em Ledyvas; prestar aos seus clientes o primeiro nível de apoio comercial (apresentação, demonstração, acompanhamento), encaminhando à Ledyvas os incidentes técnicos do software; não fazer engenharia inversa, não descompilar nem sublicenciar o software; não registar marcas, nomes comerciais ou domínios que contenham “Ledyvas” ou sejam confundíveis; cumprir a política comercial e de marca comunicada por escrito pela Ledyvas." },
      { t: "12. Obrigações da Ledyvas", b: "Fornecer o software Ledyvas Enterprise e as suas atualizações; emitir e ativar as licenças nos termos da cláusula 4; prestar todo o suporte técnico e o atendimento ao cliente do produto; fornecer a formação, a certificação e o kit de marca; e comunicar com antecedência razoável qualquer alteração ao PVP, à percentagem grossista ou às condições gerais." },
      { t: "13. Uso da marca", b: "O Distribuidor pode identificar-se como “Distribuidor Oficial da Ledyvas” e usar o kit de marca fornecido pela Ledyvas, apenas para comercializar o Ledyvas e enquanto mantiver esse estatuto. Ao perder o estatuto de Distribuidor Oficial ou ao terminar o contrato, todo o uso da marca cessa no prazo de cinco (5) dias." },
      { t: "14. Confidencialidade", b: "Cada parte protege a informação não pública da outra: preços especiais, dados de clientes, roteiro do produto, números internos e condições do programa. A obrigação subsiste após a cessação." },
      { t: "15. Proteção de dados", b: "Os dados de clientes e potenciais clientes tratados por cada parte são usados apenas para a comercialização do Ledyvas. Cada parte cumpre a normativa de proteção de dados que lhe seja aplicável. O Distribuidor é responsável pelo tratamento dos dados dos seus próprios clientes finais." },
      { t: "16. Duração e cessação", b: "O contrato tem uma duração de <b>um (1) ano</b> desde a assinatura e <b>não se renova automaticamente</b>. Sessenta (60) dias antes do vencimento, a Ledyvas comunica se oferece a renovação e em que termos (pode alterar a adesão, o PVP, a percentagem grossista e as condições gerais). Como referência do critério de renovação: se o Distribuidor revendeu quinze (15) ou mais licenças no período, a Ledyvas oferece a renovação com a adesão bonificada; se não revendeu nenhuma, o contrato termina no vencimento; nos casos intermédios, a renovação é oferecida ao preço de adesão em vigor. Qualquer das partes pode terminar antes com aviso escrito de trinta (30) dias, sem justa causa. A Ledyvas pode terminar de imediato por violação das cláusulas 4, 6, 11 ou 13. Ao terminar: o Distribuidor deixa de usar a marca e de comercializar o Ledyvas; as licenças já revendidas a clientes finais mantêm-se válidas e com suporte da Ledyvas." },
      { t: "17. Sem sociedade nem vínculo laboral", b: "Este contrato não cria sociedade, franquia, agência com poder de representação nem vínculo laboral entre as partes. O Distribuidor pode comercializar outros produtos, mesmo concorrentes, salvo acordo expresso em contrário." },
      { t: "18. Lei aplicável e resolução de litígios", b: "O presente contrato rege-se pelo direito da <b>República Dominicana</b>, em particular pelo Código Civil, pelo Código de Comércio e pela Lei n.º 126-02 sobre Comércio Eletrónico, Documentos e Assinaturas Digitais. Fica expressamente excluída a aplicação da Convenção das Nações Unidas sobre os Contratos de Compra e Venda Internacional de Mercadorias (Viena, 1980). As partes tentarão resolver qualquer divergência de boa-fé; não o conseguindo, submetem-se exclusivamente aos tribunais competentes da República Dominicana, renunciando expressamente a qualquer outro foro ou jurisdição, seja qual for o domicílio ou a nacionalidade das partes." },
      { t: "19. Assinatura eletrónica", b: "Ao marcar a caixa de aceitação e escrever o nome completo do representante legal, o Distribuidor dá o consentimento e assina o presente contrato nos termos da Lei n.º 126-02, com o mesmo valor legal de uma assinatura manuscrita. A Ledyvas regista a data, a hora e o endereço IP da assinatura como prova." }
    ]
  };

  var BY_ROLE = { distribuidor: DISTRIBUIDOR };

  window.ContratoTexto = {
    role: function () { return "distribuidor"; },
    title: function (role, lang) { return (TITLES[this.role(role)][lang] || TITLES[this.role(role)].es); },
    meta: function (lang) { return META[lang] || META.es; },
    parties: function (role, lang) { var m = PARTIES[this.role(role)]; return m[lang] || m.es; },
    clauses: function (role, lang) { var m = BY_ROLE[this.role(role)]; return m[lang] || m.es; }
  };
})();
